// Zero-amount-specific finalize hook
export const useFinalizeZeroAmountPayment = (cartId: string, checkoutService = CheckoutService) => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (myParksSessionToken: string) => {
      return checkoutService.finalizeZeroAmountPayment(cartId, { myParksSessionToken });
    },
    retry: retryLogic,
    scope: {
      id: paymentQueryKey(cartId).join("-"),
    },
    onSuccess: () => {
      queryClient.resetQueries({ queryKey: paymentQueryKey(cartId) });
    },
  });
};
