import {
  CreateCartRequest,
  KlarnaPaymentResponse,
  GiftCardPaymentRequestItem,
  InitializeKlarnaPaymentRequest,
  KlarnaCheckoutUi,
  UpdatePaymentRequest,
  CartRequestCartItem,
  KlarnaCheckoutShopUrls,
  UpdateCartItemRequestV2,
  UpdateCartRequest,
  GetPaymentResponse,
  FinalizeZeroAmountPaymentRequest,
  InitializeNetsPaymentRequest,
  CartResponseV2,
  AddVoucherToCartRequest,
} from "@parksandresorts/webapiproxy-types";
import ServiceHelper from "./service-helper";

const customApiBaseUrlCart = ServiceHelper.apiBaseUrl.replace("/api/", "/api/v3/");
const customApiBaseUrlPayment = ServiceHelper.apiBaseUrl.replace("/api/", "/api/v2/");

export const createCheckoutService = (apiBaseUrlCart: string, apiBaseUrlPayment: string) => ({
  createCart: (data: CreateCartRequest, language: string): Promise<CartResponseV2> => {
    return ServiceHelper.fetchPost(`webshop/cart?culture=${language}`, data, undefined, apiBaseUrlCart);
  },
  getCart(cartId: string): Promise<CartResponseV2> {
    return ServiceHelper.fetchGet(`webshop/cart/${cartId}`, undefined, apiBaseUrlCart);
  },
  patchCart: (cartId: string, data: Partial<UpdateCartRequest>): Promise<CartResponseV2> => {
    return ServiceHelper.fetchPatch(`webshop/cart/${cartId}`, data, undefined, apiBaseUrlCart);
  },
  addItemToCart: (cartId: string, product: CartRequestCartItem, language: string): Promise<CartResponseV2> => {
    return ServiceHelper.fetchPost(
      `webshop/cart/${cartId}/item?culture=${language}`,
      product,
      undefined,
      apiBaseUrlCart,
    );
  },
  removeItemFromCart: (cartId: string, cartItemGuid: string): Promise<CartResponseV2> => {
    return ServiceHelper.fetchDelete(
      `webshop/cart/${cartId}/item/${cartItemGuid}`,
      undefined,
      undefined,
      apiBaseUrlCart,
    );
  },
  patchItemInCart: (
    cartId: string,
    cartItemGuid: string,
    product: UpdateCartItemRequestV2,
  ): Promise<CartResponseV2> => {
    return ServiceHelper.fetchPatch(`webshop/cart/${cartId}/item/${cartItemGuid}`, product, undefined, apiBaseUrlCart);
  },
  addSubitemToCartItem: (
    cartId: string,
    cartItemGuid: string,
    subItem: CartRequestCartItem,
  ): Promise<CartResponseV2> => {
    return ServiceHelper.fetchPost(
      `webshop/cart/${cartId}/item/${cartItemGuid}/subitem`,
      subItem,
      undefined,
      apiBaseUrlCart,
    );
  },
  removeSubitemFromCartItem: (
    cartId: string,
    parentCartItemGuid: string,
    subItemGuid: string,
  ): Promise<CartResponseV2> => {
    return ServiceHelper.fetchDelete(
      `webshop/cart/${cartId}/item/${parentCartItemGuid}/subitem/${subItemGuid}`,
      undefined,
      undefined,
      apiBaseUrlCart,
    );
  },

  addVoucherToCart: (cartId: string, voucher: AddVoucherToCartRequest): Promise<CartResponseV2> => {
    return ServiceHelper.fetchPost(`webshop/cart/${cartId}/voucher`, voucher, undefined, apiBaseUrlCart);
  },

  removeVoucherFromCart: (cartId: string, voucherCode: string): Promise<CartResponseV2> => {
    return ServiceHelper.fetchDelete(
      `webshop/cart/${cartId}/voucher/${voucherCode}`,
      undefined,
      undefined,
      apiBaseUrlCart,
    );
  },

  createKlarnaPaymentForCart: (
    cartId: string,
    language: string,
    checkoutUrls: KlarnaCheckoutShopUrls,
    giftCards?: Array<GiftCardPaymentRequestItem>,
    styling?: KlarnaCheckoutUi,
  ): Promise<GetPaymentResponse> => {
    const body = {
      paymentProvider: "Klarna",
      locale: language,
      giftCards,
      userInterface: styling,
      shopUrls: checkoutUrls,
    } satisfies InitializeKlarnaPaymentRequest;

    return ServiceHelper.fetchPost(`webshop/cart/${cartId}/payment`, body, undefined, apiBaseUrlPayment);
  },
  createNetsPaymentForCart(
    cartId: string,
    language: string,
    giftCards?: Array<GiftCardPaymentRequestItem>,
  ): Promise<GetPaymentResponse> {
    const body = {
      paymentProvider: "Nets",
      locale: language,
      giftCards,
    } satisfies InitializeNetsPaymentRequest;
    return ServiceHelper.fetchPost(`webshop/cart/${cartId}/payment`, body, undefined, apiBaseUrlPayment);
  },
  patchPaymentForCart: (
    cartId: string,
    language: string,
    giftCards?: Array<GiftCardPaymentRequestItem>,
  ): Promise<GetPaymentResponse> => {
    const body = {
      locale: language,
      giftCards,
    } satisfies UpdatePaymentRequest;
    return ServiceHelper.fetchPatch(`webshop/cart/${cartId}/payment`, body, undefined, apiBaseUrlPayment);
  },
  getPaymentStatus: (cartId: string): Promise<GetPaymentResponse> => {
    return ServiceHelper.fetchGet(`webshop/cart/${cartId}/payment`, undefined, apiBaseUrlPayment);
  },
  addGiftCardToCart: (cartId: string, giftCard: GiftCardPaymentRequestItem): Promise<GetPaymentResponse> => {
    return ServiceHelper.fetchPost(`webshop/cart/${cartId}/payment/giftcard`, giftCard, undefined, apiBaseUrlPayment);
  },
  removeGiftCardFromCart: (cartId: string, giftCardIdentifier: string): Promise<GetPaymentResponse> => {
    return ServiceHelper.fetchDelete(
      `webshop/cart/${cartId}/payment/giftcard/${giftCardIdentifier}`,
      undefined,
      undefined,
      apiBaseUrlPayment,
    );
  },

  finalizeKlarnaOrder: (cartId: string, klarnaOrderId: string): Promise<KlarnaPaymentResponse> => {
    return ServiceHelper.fetchPost(
      `webshop/cart/${cartId}/payment/callback/klarna/finalizeorder/${klarnaOrderId}`,
      undefined,
      undefined,
      apiBaseUrlPayment,
    );
  },

  validateNetsPayment: (cartId: string): Promise<void> => {
    return ServiceHelper.fetchGet(
      `webshop/cart/${cartId}/payment/callback/nets/validate`,
      undefined,
      apiBaseUrlPayment,
    );
  },

  finalizeZeroAmountPayment: (cartId: string, request: FinalizeZeroAmountPaymentRequest): Promise<void> => {
    return ServiceHelper.fetchPost(
      `webshop/cart/${cartId}/payment/callback/zero-amount/finalize`,
      request,
      undefined,
      apiBaseUrlPayment,
    );
  },
});

export type ICheckoutService = typeof CheckoutService;

export const CheckoutService = createCheckoutService(customApiBaseUrlCart, customApiBaseUrlPayment);
