import { z } from "zod";
import {
  CreateCartErrorCode,
  InitializePaymentErrorCode,
  UpdatePaymentErrorCode,
} from "@parksandresorts/webapiproxy-types";

export const cartErrorResponseFromServer = z.object({
  status: z.number(),
  error: z.object({
    error: z.nativeEnum(CreateCartErrorCode),
    message: z.string().nullish(),
  }),
});

export const paymentErrorResponseFromServer = z.object({
  status: z.number(),
  error: z.object({
    error: z.union([z.nativeEnum(UpdatePaymentErrorCode), z.nativeEnum(InitializePaymentErrorCode)]),
    message: z.string().nullish(),
  }),
});

/**
 * Check if a generic error is matching the server error format for eithe cart or payment.
 * @param error The generic error to check
 * @returns true if the error is from the server, otherwise false
 */
export const isErrorFromServer = (error: unknown) => {
  return [cartErrorResponseFromServer, paymentErrorResponseFromServer].some(
    (schema) => schema.safeParse(error).success,
  );
};

/**
 * Tries to parse the generic error into a specific error type. Will return the parsed error if successful, otherwise undefined.
 * @param error The generic error
 * @param schemaToValidateAgainst The zod schema to validate against
 * @returns The parsed error if successful, otherwise undefined
 */
export const parseServerError = <T extends z.ZodTypeAny>(error: unknown, schemaToValidateAgainst: T) => {
  const parsed = schemaToValidateAgainst.safeParse(error);
  if (parsed.success) {
    return parsed.data as z.infer<T>;
  }
  return undefined;
};
